// Package berget speaks to Berget Code's OpenAI-compatible chat API. It
// carries no opinion about what a completion is for — prompting policy
// (how a scaffolded component is described, what the reply must look
// like) lives in implement.go.
package berget

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"time"
)

const (
	// DefaultBaseURL is the Berget Code API root. The API is
	// OpenAI-compatible, so the client speaks plain chat completions.
	DefaultBaseURL = "https://api.berget.ai/v1"

	// DefaultModel tracks Berget Code's default code model. --model
	// overrides it; pinning a model explicitly is the reproducible choice
	// for shared workspaces.
	DefaultModel = "berget-code"

	// EnvAPIKey carries the API key. It is deliberately *not* namespaced
	// INTROPY_: it is Berget's own variable, shared with every other tool
	// that speaks to the same account. Borrowed, not ours — do not rename
	// it.
	EnvAPIKey = "BERGET_API_KEY"
)

// Client speaks to Berget Code's chat completions endpoint.
type Client struct {
	baseURL   string
	apiKey    string
	model     string
	http      *http.Client
	userAgent string
}

type options struct {
	baseURL   string
	model     string
	http      *http.Client
	userAgent string
}

// Option customises NewClient.
type Option func(*options)

// WithBaseURL redirects the API root, primarily the test seam.
func WithBaseURL(u string) Option {
	return func(o *options) { o.baseURL = u }
}

// WithModel selects the model sent on every completion.
func WithModel(model string) Option {
	return func(o *options) { o.model = model }
}

// WithHTTPClient replaces the default HTTP client.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.http = c }
}

// WithUserAgent sets the User-Agent header on every request.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// NewClient builds a Client for the given API key. The key is required:
// an empty one would fail as a bare 401 far from the flag that asked for
// the call, so it is refused here instead.
func NewClient(apiKey string, opts ...Option) (*Client, error) {
	if apiKey == "" {
		return nil, fmt.Errorf("%s is not set\nset %s to a Berget Code API key to use --prompt", EnvAPIKey, EnvAPIKey)
	}
	o := options{baseURL: DefaultBaseURL, model: DefaultModel}
	for _, opt := range opts {
		opt(&o)
	}
	httpClient := o.http
	if httpClient == nil {
		// Generous but bounded: implementing several source files is a
		// long completion, and a hung request must still die on its own.
		httpClient = &http.Client{Timeout: 10 * time.Minute}
	}
	return &Client{
		baseURL:   o.baseURL,
		apiKey:    apiKey,
		model:     o.model,
		http:      httpClient,
		userAgent: o.userAgent,
	}, nil
}

// Model reports the model the client completes with, for progress output.
func (c *Client) Model() string {
	return c.model
}

// Message is one chat message. Roles are the OpenAI roles: system, user,
// assistant.
type Message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type chatRequest struct {
	Model    string    `json:"model"`
	Messages []Message `json:"messages"`
}

type chatResponse struct {
	Choices []struct {
		Message Message `json:"message"`
	} `json:"choices"`
}

// Complete runs one chat completion and returns the first choice's
// content. The reply is raw model output; parsing it is the caller's
// contract with the prompt it wrote.
func (c *Client) Complete(ctx context.Context, messages []Message) (string, error) {
	body, err := json.Marshal(chatRequest{Model: c.model, Messages: messages})
	if err != nil {
		return "", err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/chat/completions", bytes.NewReader(body))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+c.apiKey)
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return "", fmt.Errorf("berget request: %w", err)
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return "", fmt.Errorf("read berget response: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		return "", apiError(resp.StatusCode, data)
	}

	var parsed chatResponse
	if err := json.Unmarshal(data, &parsed); err != nil {
		return "", fmt.Errorf("parse berget response: %w", err)
	}
	if len(parsed.Choices) == 0 {
		return "", errors.New("berget returned no completion choices")
	}
	return parsed.Choices[0].Message.Content, nil
}

// apiError surfaces the server's own error message when it sends one —
// an OpenAI-shaped {"error":{"message":...}} — and falls back to the
// status line otherwise. The model name is not repeated: the caller's
// error wrap names the operation.
func apiError(status int, body []byte) error {
	var e struct {
		Err struct {
			Message string `json:"message"`
		} `json:"error"`
	}
	if json.Unmarshal(body, &e) == nil && e.Err.Message != "" {
		return fmt.Errorf("berget api: %s (status %d)", e.Err.Message, status)
	}
	return fmt.Errorf("berget api: status %d", status)
}

package berget

import (
	"context"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"
)

// Gathering caps keep a scaffold inside one completion's context window.
// A rendered skeleton is source code, not data, so a component that
// exceeds them is already past what a single prompt can faithfully
// implement; the files are listed as omitted rather than silently
// dropped, so the model answers against the true file tree.
const (
	maxFileBytes  = 64 << 10
	maxTotalBytes = 256 << 10
)

// File is one file the model created or rewrote. Path is relative to the
// component root; Content is the file's complete new contents.
type File struct {
	Path    string `json:"path"`
	Content string `json:"content"`
}

// ImplementOptions describes one implement run.
type ImplementOptions struct {
	// Dir is the scaffolded component root. It is read for context and
	// written with the files the model returns.
	Dir string

	// Prompt is the user's description of what the component should do.
	Prompt string

	// Template names the scaffold template the component came from, so
	// the model knows which conventions the skeleton follows.
	Template string
}

// systemPrompt is the output contract. The model answers with JSON only
// so the reply parses without a markdown or prose tolerance layer.
const systemPrompt = `You are implementing a component in an Intropy integration workspace. The user scaffolded the component from a template and gives you the scaffolded file tree plus a description of what the component should do.

Rewrite or add the source files needed to implement the description. Keep the scaffold's structure, naming, and configuration files intact unless the description requires a change. The scaffold record (.intropy/scaffold.json) is machine-managed; never return it.

Respond with JSON only, no prose and no code fences, in this exact shape:
{"files":[{"path":"relative/path.ext","content":"full file contents"}]}
- paths are relative to the component root and use forward slashes
- include every file you create or change, with its complete new contents
- omit files you leave unchanged`

// Implement asks the model to implement the scaffolded component per the
// prompt and writes the returned files into Dir. It returns the files
// written. A malformed reply is an error and writes nothing: the parse
// completes before any file lands, so a bad completion cannot leave the
// component half-implemented.
func (c *Client) Implement(ctx context.Context, opts ImplementOptions) ([]File, error) {
	dump, err := dumpTree(opts.Dir)
	if err != nil {
		return nil, err
	}

	reply, err := c.Complete(ctx, []Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: fmt.Sprintf("%s\n\nScaffolded from template %q. Current files:\n\n%s", opts.Prompt, opts.Template, dump)},
	})
	if err != nil {
		return nil, err
	}

	files, err := parseFiles(reply)
	if err != nil {
		return nil, err
	}
	for _, f := range files {
		if err := writeFile(opts.Dir, f); err != nil {
			return nil, err
		}
	}
	return files, nil
}

// parseFiles extracts the file set from the model's reply. The strict
// shape is the whole reply as one JSON object; a reply wrapped in a
// markdown code fence is unwrapped first, because that is the one
// deviation code models reliably produce despite instructions.
func parseFiles(reply string) ([]File, error) {
	text := strings.TrimSpace(reply)
	if strings.HasPrefix(text, "```") {
		if i := strings.Index(text, "\n"); i >= 0 {
			text = text[i+1:]
		}
		text = strings.TrimSuffix(strings.TrimSpace(text), "```")
		text = strings.TrimSpace(text)
	}

	var parsed struct {
		Files []File `json:"files"`
	}
	if err := json.Unmarshal([]byte(text), &parsed); err != nil {
		return nil, fmt.Errorf("berget reply is not the expected JSON file set: %w\nre-run the command; if it persists, the model is not following the output contract", err)
	}
	if len(parsed.Files) == 0 {
		return nil, fmt.Errorf("berget reply lists no files\nmake the prompt more specific about what the component should do")
	}
	for _, f := range parsed.Files {
		if !filepath.IsLocal(f.Path) {
			return nil, fmt.Errorf("berget reply names %q, which escapes the component directory\nre-run the command; if it persists, the model is not following the output contract", f.Path)
		}
	}
	return parsed.Files, nil
}

// writeFile writes one returned file inside the component root. The path
// was validated by parseFiles, so joining cannot escape the root.
func writeFile(root string, f File) error {
	path := filepath.Join(root, f.Path)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(f.Content), 0o644)
}

// dumpTree renders the component's file tree as the prompt's context
// block. Files are sorted for a deterministic prompt; binaries and
// oversized files are listed as omitted rather than sent.
func dumpTree(root string) (string, error) {
	var b strings.Builder
	total := 0
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)

		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		switch {
		case !isText(data):
			fmt.Fprintf(&b, "--- %s ---\n(binary file, omitted)\n\n", rel)
		case len(data) > maxFileBytes:
			fmt.Fprintf(&b, "--- %s ---\n(%d bytes, over the per-file limit, omitted)\n\n", rel, len(data))
		case total+len(data) > maxTotalBytes:
			fmt.Fprintf(&b, "--- %s ---\n(component over the total context limit, omitted)\n\n", rel)
		default:
			total += len(data)
			fmt.Fprintf(&b, "--- %s ---\n%s\n\n", rel, data)
		}
		return nil
	})
	if err != nil {
		return "", fmt.Errorf("read component files: %w", err)
	}
	return b.String(), nil
}

// isText reports whether data is safe to embed in a prompt: valid UTF-8
// with no NUL bytes, the same heuristic git uses for binary detection.
func isText(data []byte) bool {
	probe := data
	if len(probe) > 8000 {
		probe = probe[:8000]
	}
	return utf8.Valid(probe) && !strings.ContainsRune(string(probe), 0)
}

// sortedFiles is a helper for tests and verbose reporting: the returned
// paths in stable order.
func sortedFiles(files []File) []string {
	paths := make([]string, 0, len(files))
	for _, f := range files {
		paths = append(paths, f.Path)
	}
	sort.Strings(paths)
	return paths
}

