package berget

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// newTestServer stubs the chat completions endpoint and records the last
// request it saw, so tests can assert both sides of the wire.
func newTestServer(t *testing.T, status int, reply string) (*httptest.Server, *chatRequest) {
	t.Helper()
	var got chatRequest
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/chat/completions" {
			t.Errorf("path = %q, want /v1/chat/completions", r.URL.Path)
		}
		if r.Header.Get("Authorization") != "Bearer test-key" {
			t.Errorf("authorization = %q, want bearer token", r.Header.Get("Authorization"))
		}
		body, _ := io.ReadAll(r.Body)
		if err := json.Unmarshal(body, &got); err != nil {
			t.Errorf("request body is not a chat request: %v", err)
		}
		w.WriteHeader(status)
		io.WriteString(w, reply)
	}))
	t.Cleanup(srv.Close)
	return srv, &got
}

func TestNewClientRequiresKey(t *testing.T) {
	if _, err := NewClient(""); err == nil {
		t.Fatal("empty API key accepted")
	} else if !strings.Contains(err.Error(), EnvAPIKey) {
		t.Errorf("error %q does not name %s", err, EnvAPIKey)
	}
}

func TestComplete(t *testing.T) {
	srv, got := newTestServer(t, http.StatusOK, `{"choices":[{"message":{"role":"assistant","content":"hello"}}]}`)

	c, err := NewClient("test-key", WithBaseURL(srv.URL+"/v1"), WithModel("test-model"))
	if err != nil {
		t.Fatalf("NewClient: %v", err)
	}
	content, err := c.Complete(context.Background(), []Message{{Role: "user", Content: "hi"}})
	if err != nil {
		t.Fatalf("Complete: %v", err)
	}
	if content != "hello" {
		t.Errorf("content = %q, want %q", content, "hello")
	}
	if got.Model != "test-model" {
		t.Errorf("request model = %q, want test-model", got.Model)
	}
	if len(got.Messages) != 1 || got.Messages[0].Content != "hi" {
		t.Errorf("request messages = %+v", got.Messages)
	}
}

func TestCompleteAPIError(t *testing.T) {
	t.Run("server message is surfaced", func(t *testing.T) {
		srv, _ := newTestServer(t, http.StatusUnauthorized, `{"error":{"message":"invalid api key"}}`)
		c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
		_, err := c.Complete(context.Background(), nil)
		if err == nil || !strings.Contains(err.Error(), "invalid api key") {
			t.Errorf("err = %v, want the server's message", err)
		}
	})

	t.Run("unshaped body falls back to the status", func(t *testing.T) {
		srv, _ := newTestServer(t, http.StatusBadGateway, `<html>bad gateway</html>`)
		c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
		_, err := c.Complete(context.Background(), nil)
		if err == nil || !strings.Contains(err.Error(), "502") {
			t.Errorf("err = %v, want the status", err)
		}
	})

	t.Run("no choices is an error", func(t *testing.T) {
		srv, _ := newTestServer(t, http.StatusOK, `{"choices":[]}`)
		c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
		if _, err := c.Complete(context.Background(), nil); err == nil {
			t.Error("empty choices accepted")
		}
	})
}

package berget

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeScaffold seeds a component root the way a rendered template would.
func writeScaffold(t *testing.T, files map[string]string) string {
	t.Helper()
	dir := t.TempDir()
	for rel, content := range files {
		path := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return dir
}

// implementServer answers every completion with the given reply body.
func implementServer(t *testing.T, reply string) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintf(w, `{"choices":[{"message":{"role":"assistant","content":%s}}]}`, reply)
	}))
	t.Cleanup(srv.Close)
	return srv
}

func TestImplementWritesReturnedFiles(t *testing.T) {
	dir := writeScaffold(t, map[string]string{
		"Program.cs":             "// TODO: implement\n",
		".intropy/scaffold.json": `{"schemaVersion":1}` + "\n",
	})
	reply := `{"files":[{"path":"Program.cs","content":"// sums orders\n"},{"path":"Domain/Sum.cs","content":"public static class Sum {}\n"}]}`
	srv := implementServer(t, quoted(reply))

	c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
	files, err := c.Implement(context.Background(), ImplementOptions{
		Dir:      dir,
		Prompt:   "sum incoming orders",
		Template: "hello-world",
	})
	if err != nil {
		t.Fatalf("Implement: %v", err)
	}
	if len(files) != 2 {
		t.Fatalf("files = %v, want 2", files)
	}
	if got, _ := os.ReadFile(filepath.Join(dir, "Program.cs")); string(got) != "// sums orders\n" {
		t.Errorf("Program.cs = %q", got)
	}
	if got, _ := os.ReadFile(filepath.Join(dir, "Domain", "Sum.cs")); string(got) != "public static class Sum {}\n" {
		t.Errorf("Domain/Sum.cs = %q", got)
	}
}

func TestImplementSendsScaffoldContext(t *testing.T) {
	dir := writeScaffold(t, map[string]string{
		"Program.cs": "// TODO: implement\n",
		"logo.png":   "not really a png but \x00 binary",
	})
	var prompt string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		decodeBody(t, r, &req)
		prompt = req.Messages[len(req.Messages)-1].Content
		fmt.Fprint(w, `{"choices":[{"message":{"role":"assistant","content":"{\"files\":[{\"path\":\"a.txt\",\"content\":\"x\"}]}"}}]}`)
	}))
	t.Cleanup(srv.Close)

	c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
	if _, err := c.Implement(context.Background(), ImplementOptions{
		Dir:      dir,
		Prompt:   "sum incoming orders",
		Template: "hello-world",
	}); err != nil {
		t.Fatalf("Implement: %v", err)
	}
	for _, want := range []string{"sum incoming orders", "hello-world", "--- Program.cs ---", "// TODO: implement"} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt is missing %q", want)
		}
	}
	// The binary file is announced but its bytes never enter the prompt.
	if !strings.Contains(prompt, "--- logo.png ---") || !strings.Contains(prompt, "omitted") {
		t.Errorf("binary file is not announced as omitted:\n%s", prompt)
	}
	if strings.Contains(prompt, "not really a png") {
		t.Error("binary contents leaked into the prompt")
	}
}

func TestParseFiles(t *testing.T) {
	t.Run("plain JSON", func(t *testing.T) {
		files, err := parseFiles(`{"files":[{"path":"a.txt","content":"x"}]}`)
		if err != nil || len(files) != 1 || files[0].Path != "a.txt" {
			t.Errorf("files = %v, err = %v", files, err)
		}
	})

	t.Run("code-fenced JSON is unwrapped", func(t *testing.T) {
		reply := "```json\n{\"files\":[{\"path\":\"a.txt\",\"content\":\"x\"}]}\n```"
		files, err := parseFiles(reply)
		if err != nil || len(files) != 1 {
			t.Errorf("files = %v, err = %v", files, err)
		}
	})

	t.Run("prose is rejected", func(t *testing.T) {
		if _, err := parseFiles("I changed the file for you."); err == nil {
			t.Error("prose reply accepted")
		}
	})

	t.Run("empty file set is rejected", func(t *testing.T) {
		if _, err := parseFiles(`{"files":[]}`); err == nil {
			t.Error("empty file set accepted")
		}
	})

	t.Run("escaping paths are rejected", func(t *testing.T) {
		for _, path := range []string{"../evil.txt", "/abs/evil.txt", "sub/../../evil.txt"} {
			reply := fmt.Sprintf(`{"files":[{"path":%q,"content":"x"}]}`, path)
			if _, err := parseFiles(reply); err == nil {
				t.Errorf("path %q accepted", path)
			}
		}
