func TestImplementRejectsTraversalWithoutWriting(t *testing.T) {
	dir := writeScaffold(t, map[string]string{"Program.cs": "// TODO\n"})
	reply := `{"files":[{"path":"Program.cs","content":"ok\n"},{"path":"../evil.txt","content":"x"}]}`
	srv := implementServer(t, quoted(reply))

	c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
	_, err := c.Implement(context.Background(), ImplementOptions{Dir: dir, Prompt: "x", Template: "t"})
	if err == nil {
		t.Fatal("traversal path accepted")
	}
	// The whole parse precedes any write, so even the valid file must not
	// have landed.
	if got, _ := os.ReadFile(filepath.Join(dir, "Program.cs")); string(got) != "// TODO\n" {
		t.Error("a failed parse still wrote files")
	}
	if _, statErr := os.Stat(filepath.Join(dir, "..", "evil.txt")); statErr == nil {
		t.Error("file written outside the component root")
	}
}

// quoted turns a raw JSON file-set reply into the JSON string literal the
// completion carries it as.
func quoted(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

