// Complete runs one chat completion and returns the first choice's
// content. The reply is raw model output; parsing it is the caller's
// contract with the prompt it wrote.
func (c *Client) Complete(ctx context.Context, messages []Message) (string, error) {
	resp, err := c.post(ctx, messages, false)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return "", fmt.Errorf("read berget response: %w", err)
	}
	var parsed chatResponse
	if err := json.Unmarshal(data, &parsed); err != nil {
		return "", fmt.Errorf("parse berget response: %w", err)
	}
	if len(parsed.Choices) == 0 {
		return "", errors.New("berget returned no completion choices")
	}
	return parsed.Choices[0].Message.Content, nil
}

// CompleteStream runs one streaming chat completion, invoking onDelta
// with each piece of content as it arrives, and returns the full reply.
// Long generations look hung without it: a multi-file implementation can
// run for minutes, and the stream is the only signal distinguishing a
// thinking model from a dead request.
func (c *Client) CompleteStream(ctx context.Context, messages []Message, onDelta func(string)) (string, error) {
	resp, err := c.post(ctx, messages, true)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	// SSE lines carry JSON chunks, which grow with the generated file
	// contents; the default scanner buffer would truncate them.
	scanner := bufio.NewScanner(resp.Body)
	scanner.Buffer(make([]byte, 64<<10), 4<<20)

	var content strings.Builder
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		data, ok := bytes.CutPrefix(line, []byte("data:"))
		if !ok {
			continue // comments and keep-alive blanks
		}
		data = bytes.TrimSpace(data)
		if bytes.Equal(data, []byte("[DONE]")) {
			break
		}
		var chunk chatStreamChunk
		if err := json.Unmarshal(data, &chunk); err != nil || len(chunk.Choices) == 0 {
			continue
		}
		delta := chunk.Choices[0].Delta.Content
		content.WriteString(delta)
		if onDelta != nil {
			onDelta(delta)
		}
	}
	if err := scanner.Err(); err != nil {
		return "", fmt.Errorf("read berget stream: %w", err)
	}
	if content.Len() == 0 {
		return "", errors.New("berget returned an empty stream")
	}
	return content.String(), nil
}

// post issues the chat request shared by Complete and CompleteStream. A
// non-200 status is an error here, before the caller commits to a body
// shape it cannot parse.
func (c *Client) post(ctx context.Context, messages []Message, stream bool) (*http.Response, error) {
	body, err := json.Marshal(chatRequest{Model: c.model, Messages: messages, Stream: stream})
	if err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/chat/completions", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+c.apiKey)
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return nil, fmt.Errorf("berget request: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		defer resp.Body.Close()
		data, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		return nil, apiError(resp.StatusCode, data)
	}
	return resp, nil
}

