user := fmt.Sprintf("%s\nDescription: %s\n\nScaffolded files:\n\n%s", implementContext(opts.Dir, opts.Template), opts.Prompt, dump)
messages := []Message{
	{Role: "system", Content: systemPrompt},
	{Role: "user", Content: user},
}

// Smaller models break the JSON contract with surrounding prose. The
// tolerant parse absorbs most of that; for the rest, one corrective
// retry with the offending reply in view is far cheaper than making
// the user re-run a multi-minute generation by hand. One retry, not
// a loop: a model that ignores two contracts will ignore a third.
var files []File
for attempt := 0; ; attempt++ {
	reply, err := c.complete(ctx, messages, opts.OnDelta)
	if err != nil {
		return nil, err
	}
	files, err = parseFiles(reply)
	if err == nil {
		break
	}
	if attempt > 0 {
		return nil, err
	}
	messages = append(messages,
		Message{Role: "assistant", Content: reply},
		Message{Role: "user", Content: "Your reply was not the required JSON file set. Respond again with JSON only, no prose and no code fences."},
	)
}

edits.oldText:
// parseFiles extracts the file set from the model's reply. The strict
// shape is the whole reply as one JSON object; a reply wrapped in a
// markdown code fence is unwrapped first, because that is the one
// deviation code models reliably produce despite instructions.
func parseFiles(reply string) ([]File, error) {
	text := strings.TrimSpace(reply)
	if strings.HasPrefix(text, "```") {
		if i := strings.Index(text, "\n"); i >= 0 {
			text = text[i+1:]
		}
		text = strings.TrimSuffix(strings.TrimSpace(text), "```")
		text = strings.TrimSpace(text)
	}

	var parsed struct {
		Files []File `json:"files"`
	}
	if err := json.Unmarshal([]byte(text), &parsed); err != nil {
		return nil, fmt.Errorf("berget reply is not the expected JSON file set: %w\nre-run the command; if it persists, the model is not following the output contract", err)
	}
	if len(parsed.Files) == 0 {
		return nil, fmt.Errorf("berget reply lists no files\nmake the prompt more specific about what the component should do")
	}
	for _, f := range parsed.Files {
		if !filepath.IsLocal(f.Path) {
			return nil, fmt.Errorf("berget reply names %q, which escapes the component directory\nre-run the command; if it persists, the model is not following the output contract", f.Path)
		}
	}
	return parsed.Files, nil
}

