if bergetClient != nil {
	fmt.Fprintf(stderr, "implementing %s with %s\n", outputDir, bergetClient.Model())
	progress := newStreamProgress(stderr, bergetClient.Model())
	files, err := bergetClient.Implement(ctx, berget.ImplementOptions{
		Dir:      outputDir,
		Prompt:   intCreateFlags.prompt,
		Template: args[0],
		OnDelta:  progress.delta,
	})
	progress.finish()
	if err != nil {
		return fmt.Errorf("implement %s: %w", outputDir, err)
	}
	fmt.Fprintf(stderr, "implemented %d files in %s\n", len(files), outputDir)
}

// streamProgress renders generation progress on stderr. A terminal gets
// one line updated in place; anything else (CI logs, pipes) gets a line
// every 16 KiB, because an in-place update is invisible there and total
// silence for minutes reads as a hang.
type streamProgress struct {
	w        io.Writer
	model    string
	tty      bool
	received int
	reported int
}

func newStreamProgress(w io.Writer, model string) *streamProgress {
	p := &streamProgress{w: w, model: model}
	if f, ok := w.(*os.File); ok {
		p.tty = term.IsTerminal(int(f.Fd()))
	}
	return p
}

func (p *streamProgress) delta(s string) {
	p.received += len(s)
	if p.tty {
		fmt.Fprintf(p.w, "\r\x1b[Kreceiving from %s... %s", p.model, humanBytes(p.received))
		return
	}
	if p.received-p.reported >= 16<<10 {
		fmt.Fprintf(p.w, "receiving from %s... %s\n", p.model, humanBytes(p.received))
		p.reported = p.received
	}
}

// finish clears the in-place line so the next message starts clean. On a
// non-terminal there is nothing to clear.
func (p *streamProgress) finish() {
	if p.tty && p.received > 0 {
		fmt.Fprint(p.w, "\r\x1b[K")
	}
}

// humanBytes renders a byte count for progress lines: bytes while small,
// kibibytes past that.
func humanBytes(n int) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", n)
	}
	return fmt.Sprintf("%.1f KiB", float64(n)/1024)
}

