+		fmt.Fprintf(p.w, "\r\x1b[Kreceiving from %s... %s", p.model, humanBytes(p.received))
+		return
+	}
+	if p.received-p.reported >= 16<<10 {
+		fmt.Fprintf(p.w, "receiving from %s... %s\n", p.model, humanBytes(p.received))
+		p.reported = p.received
+	}
+}
+
+// finish clears the in-place line so the next message starts clean. On a
+// non-terminal there is nothing to clear.
+func (p *streamProgress) finish() {
+	if p.tty && p.received > 0 {
+		fmt.Fprint(p.w, "\r\x1b[K")
+	}
+}
+
+// humanBytes renders a byte count for progress lines: bytes while small,
+// kibibytes past that.
+func humanBytes(n int) string {
+	if n < 1024 {
+		return fmt.Sprintf("%d B", n)
+	}
+	return fmt.Sprintf("%.1f KiB", float64(n)/1024)
+}
+
