package berget

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// Gathering caps keep a scaffold inside one completion's context window.
// A rendered skeleton is source code, not data, so a component that
// exceeds them is already past what a single prompt can faithfully
// implement; the files are listed as omitted rather than silently
// dropped, so the model answers against the true file tree. Dependencies
// get the smaller share: they are context, not the subject.
const (
	maxFileBytes  = 64 << 10
	maxTotalBytes = 256 << 10
	maxDepBytes   = 128 << 10
)

// maxRepairRounds bounds the build-and-repair loop: after this many
// repair generations the files are left on disk and the failure is
// reported, because a model that cannot fix its own errors in two tries
// is not going to manage a third.
const maxRepairRounds = 2

// correctionPrompt follows a reply that broke the JSON contract, showing
// the model its own reply before asking again.
const correctionPrompt = "Your reply was not the required JSON file set. Respond again with JSON only, no prose and no code fences."

// skipDirs are directory names never sent as context: VCS state and
// build output are large, generated, and say nothing about the code to
// write.
var skipDirs = map[string]bool{".git": true, "bin": true, "obj": true, "node_modules": true}

// File is one file the model created or rewrote. Path is relative to the
// component root; Content is the file's complete new contents.
type File struct {
	Path    string `json:"path"`
	Content string `json:"content"`
}

// ImplementOptions describes one implement run.
type ImplementOptions struct {
	// Dir is the scaffolded component root. It is read for context and
	// written with the files the model returns.
	Dir string

	// Prompt is the user's description of what the component should do.
	Prompt string

	// Template names the scaffold template the component came from, so
	// the model knows which conventions the skeleton follows.
	Template string

	// OnDelta, when set, is invoked with each piece of the model's
	// output as it streams in. Long generations look hung without it;
	// callers use it for progress output. Nil selects the non-streaming
	// request.
	OnDelta func(Delta)

	// Verify, when set, checks the written component after each round —
	// typically compiling it. A nil error means the component is done; a
	// non-nil error's message becomes the repair brief fed back to the
	// model, so it should carry the build's actual errors, trimmed.
	Verify func(ctx context.Context, dir string) error

	// Notes receives progress lines (repair rounds, verification). Nil
	// discards them.
	Notes io.Writer
}

// ImplementResult reports what an implement run did.
type ImplementResult struct {
	// Files is the union of every file written across all rounds, keyed
	// by path and sorted; later rounds overwrite earlier contents.
	Files []File

	// Verified is the final Verify outcome: the last build passed, or
	// there was nothing to verify with. False means the repair loop ran
	// out and the component on disk does not build.
	Verified bool

	// Rounds counts the repair generations that ran.
	Rounds int

	// LastVerifyErr carries the final build failure when Verified is
	// false, so the caller can show what the model could not fix.
	LastVerifyErr error
}

// systemPrompt is the output contract and nothing else. It stays static
// on purpose: OpenAI-compatible endpoints cache prompt prefixes, so
// everything that varies between components — template, values, message
// wiring — belongs in the user message instead.
const systemPrompt = `You are implementing a component in an Intropy integration workspace. The user scaffolded the component from a template and gives you the component's context, the scaffolded file tree, and a description of what the component should do.

Rewrite or add the source files needed to implement the description, consistently with the component context: wire the messages the rendered values declare, in the direction the block kind implies, and conform to the dependency projects' types exactly — never invent fields they do not have. Keep the scaffold's structure, naming, and configuration files intact unless the description requires a change. The scaffold record (.intropy/scaffold.json) is machine-managed; never return it.

Respond with JSON only, no prose and no code fences, in this exact shape:
{"files":[{"path":"relative/path.ext","content":"full file contents"}]}
- paths are relative to the component root and use forward slashes
- include every file you create or change, with its complete new contents
- omit files you leave unchanged`

// Implement asks the model to implement the scaffolded component per the
// prompt and writes the returned files into Dir. When Verify is set, a
// failed check triggers the build-and-repair loop: the errors go back to
// the model, which returns a corrected file set, up to maxRepairRounds
// times. A malformed reply writes nothing: the parse completes before
// any file lands, so a bad completion cannot leave the component
// half-implemented.
func (c *Client) Implement(ctx context.Context, opts ImplementOptions) (ImplementResult, error) {
	// The record feeds both the context section and the dependency dump.
	// Best-effort: the create just wrote it, but an unreadable record
	// must degrade the context, not fail the implement.
	rec, _ := template.LoadScaffold(filepath.Join(opts.Dir, template.ScaffoldRelPath))

	var b strings.Builder
	b.WriteString(implementContext(rec, opts.Template))
	b.WriteString(dependencyContext(opts.Dir, rec))
	fmt.Fprintf(&b, "Description: %s\n\nScaffolded files:\n\n", opts.Prompt)
	if _, err := dumpTreeInto(&b, opts.Dir, maxTotalBytes, ""); err != nil {
		return ImplementResult{}, err
	}

	messages := []Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: b.String()},
	}

	files, reply, err := c.generate(ctx, &messages, opts.OnDelta)
	if err != nil {
		return ImplementResult{}, err
	}
	if err := writeFiles(opts.Dir, files); err != nil {
		return ImplementResult{}, err
	}
	written := indexFiles(files)

	result := ImplementResult{Verified: true}
	if opts.Verify == nil {
		result.Files = sortedFiles(written)
		return result, nil
	}

	for round := 1; ; round++ {
		note(opts.Notes, "verifying the component builds")
		verr := opts.Verify(ctx, opts.Dir)
		if verr == nil {
			result.Rounds = round - 1
			break
		}
		if round > maxRepairRounds {
			result.Verified = false
			result.Rounds = maxRepairRounds
			result.LastVerifyErr = verr
			break
		}
		note(opts.Notes, fmt.Sprintf("build failed; asking %s to repair (round %d of %d)", c.model, round, maxRepairRounds))
		messages = append(messages,
			Message{Role: "assistant", Content: reply},
			Message{Role: "user", Content: repairBrief(verr)},
		)
		files, reply, err = c.generate(ctx, &messages, opts.OnDelta)
		if err != nil {
			result.Files = sortedFiles(written)
			return result, err
		}
		if err := writeFiles(opts.Dir, files); err != nil {
			return result, err
		}
		for _, f := range files {
			written[f.Path] = f
		}
	}
	result.Files = sortedFiles(written)
	return result, nil
}

// generate completes once and parses the file set. Smaller models break
// the JSON contract with surrounding prose; the tolerant parse absorbs
// most of that, and for the rest one corrective retry with the offending
// reply in view is far cheaper than making the user re-run a multi-minute
// generation by hand. One retry, not a loop: a model that ignores two
// contracts will ignore a third. The reply travels back so the caller can
// append it to the conversation.
func (c *Client) generate(ctx context.Context, messages *[]Message, onDelta func(Delta)) ([]File, string, error) {
	var lastErr error
	for attempt := 0; attempt < 2; attempt++ {
		reply, err := c.complete(ctx, *messages, onDelta)
		if err != nil {
			return nil, "", err
		}
		files, err := parseFiles(reply)
		if err == nil {
			return files, reply, nil
		}
		lastErr = err
		*messages = append(*messages,
			Message{Role: "assistant", Content: reply},
			Message{Role: "user", Content: correctionPrompt},
		)
	}
	return nil, "", lastErr
}

// repairBrief turns a verification failure into the next user message.
// The errors are the brief; the shape reminder exists because a model
// deep in a conversation drifts from a contract set at the start.
func repairBrief(verr error) string {
	return fmt.Sprintf("The component does not build. The build reports:\n\n%s\n\nReturn the corrected file set: the complete new contents of every file that must change, as JSON only, in the same shape as before.", verr)
}

// complete dispatches to the streaming or one-shot completion.
func (c *Client) complete(ctx context.Context, messages []Message, onDelta func(Delta)) (string, error) {
	if onDelta != nil {
		// A nil handler is still installed so the streaming path is
		// exercised identically; the callback filters empty deltas.
		return c.CompleteStream(ctx, messages, onDelta)
	}
	return c.Complete(ctx, messages)
}

// implementContext renders the "Component context" section of the user
// message from the scaffold record the create just wrote: which template
// and version the component came from, the role its block kind plays in
// the integration, and the values it was rendered with. The record is
// also in the file dump, but buried; surfacing it as labeled facts is
// what lets the model wire messages in the right direction rather than
// guess. A nil record degrades to the template name alone.
func implementContext(rec *template.Scaffold, templateName string) string {
	var b strings.Builder
	b.WriteString("Component context:\n")
	fmt.Fprintf(&b, "- scaffolded from template %q", templateName)
	if rec == nil {
		b.WriteString("\n\n")
		return b.String()
	}
	if rec.Version != "" {
		fmt.Fprintf(&b, " (version %s)", rec.Version)
	}
	b.WriteString("\n")
	if rec.BlockKind != "" {
		fmt.Fprintf(&b, "- block kind: %s%s\n", rec.BlockKind, blockKindNote(rec))
	}
	if rec.Role != "" {
		fmt.Fprintf(&b, "- template role: %s\n", rec.Role)
	}
	// Map keys marshal in sorted order, so the line is deterministic and
	// a cached prefix stays cached when only later sections change.
	if len(rec.Values) > 0 {
		if data, err := json.Marshal(rec.Values); err == nil {
			fmt.Fprintf(&b, "- rendered with values: %s\n", data)
		}
	}
	b.WriteString("\n")
	return b.String()
}

// blockKindNote glosses a block kind with what it means for the code the
// model is about to write: the message direction the component wires and
// which side the external system sits on.
func blockKindNote(rec *template.Scaffold) string {
	var parts []string
	switch template.MessageDirection(rec.BlockKind) {
	case template.MessageDirectionPublish:
		parts = append(parts, "publishes messages")
	case template.MessageDirectionSubscribe:
		parts = append(parts, "subscribes to messages")
	case template.MessageDirectionNone:
		if rec.BlockKind == template.BlockKindTransactional {
			parts = append(parts, "talks with the external system directly, wires no messages")
		}
	}
	switch rec.DataFlow {
	case "in":
		parts = append(parts, "flows data in from the external system")
	case "out":
		parts = append(parts, "flows data out to the external system")
	}
	if len(parts) == 0 {
		return ""
	}
	return " (" + strings.Join(parts, "; ") + ")"
}

// dependencyContext renders the component's dependency projects as
// read-only context. A component that publishes a contract type must
// match its definition, and the definition lives in the sibling project
// — without it the model guesses field names. Paths keep their ../
// prefix so the model cannot confuse them with component files; the
// parse-side IsLocal check refuses them regardless.
func dependencyContext(root string, rec *template.Scaffold) string {
	if rec == nil || len(rec.DependsOn) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("Dependency projects (read-only context; never return files for these):\n\n")
	budget := maxDepBytes
	for _, dep := range rec.DependsOn {
		depDir := filepath.Join(root, filepath.FromSlash(dep.Dir))
		prefix := strings.TrimSuffix(dep.Dir, "/") + "/"
		used, err := dumpTreeInto(&b, depDir, budget, prefix)
		if err != nil {
			// A missing dependency directory is listed, not fatal: the
			// model should know the dependency exists even when its
			// sources cannot be read.
			fmt.Fprintf(&b, "--- %s ---\n(could not be read: %v)\n\n", dep.Dir, err)
			continue
		}
		budget -= used
		if budget <= 0 {
			break
		}
	}
	b.WriteString("\n")
	return b.String()
}

// parseFiles extracts the file set from the model's reply. The strict
// shape is the whole reply as one JSON object, but code models reliably
// deviate in a few known ways — a markdown fence, a reasoning block,
// leading prose — so the reply is tried under each tolerance in turn.
func parseFiles(reply string) ([]File, error) {
	var parsed struct {
		Files []File `json:"files"`
	}
	parsedOK := false
	for _, candidate := range replyCandidates(reply) {
		if err := json.Unmarshal([]byte(candidate), &parsed); err == nil {
			parsedOK = true
			break
		}
	}
	if !parsedOK {
		return nil, fmt.Errorf("berget reply is not the expected JSON file set (reply begins %q)\ntry a different --model, or make the prompt more specific", snippet(reply))
	}
	if len(parsed.Files) == 0 {
		return nil, fmt.Errorf("berget reply lists no files\nmake the prompt more specific about what the component should do")
	}
	for _, f := range parsed.Files {
		if !filepath.IsLocal(f.Path) {
			return nil, fmt.Errorf("berget reply names %q, which escapes the component directory\nre-run the command; if it persists, the model is not following the output contract", f.Path)
		}
	}
	return parsed.Files, nil
}

// replyCandidates yields the reply under each tolerance, most strict
// first: verbatim, unwrapped from a code fence, past a reasoning block,
// and finally the span between the outermost braces, which is where the
// JSON sits when the model frames it in prose.
func replyCandidates(reply string) []string {
	text := strings.TrimSpace(reply)
	candidates := []string{text}

	fenced := text
	if strings.HasPrefix(fenced, "```") {
		if i := strings.Index(fenced, "\n"); i >= 0 {
			fenced = fenced[i+1:]
		}
		fenced = strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(fenced), "```"))
		candidates = append(candidates, fenced)
	}

	// Reasoning models emit a think block before the answer; the answer
	// is what follows it.
	if i := strings.LastIndex(text, "</think>"); i >= 0 {
		text = strings.TrimSpace(text[i+len("</think>"):])
		candidates = append(candidates, text)
	}

	if start := strings.Index(text, "{"); start >= 0 {
		if end := strings.LastIndex(text, "}"); end > start {
			candidates = append(candidates, text[start:end+1])
		}
	}
	return candidates
}

// snippet quotes the head of a reply for an error message, so a contract
// failure shows what the model actually said instead of a bare parse
// error.
func snippet(reply string) string {
	text := strings.TrimSpace(reply)
	const max = 80
	if len(text) > max {
		text = text[:max] + "…"
	}
	return text
}

// writeFiles writes one returned file set inside the component root. The
// paths were validated by parseFiles, so joining cannot escape the root.
func writeFiles(root string, files []File) error {
	for _, f := range files {
		path := filepath.Join(root, f.Path)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, []byte(f.Content), 0o644); err != nil {
			return err
		}
	}
	return nil
}

// indexFiles keys a file set by path so later rounds overwrite earlier
// contents of the same file.
func indexFiles(files []File) map[string]File {
	out := make(map[string]File, len(files))
	for _, f := range files {
		out[f.Path] = f
	}
	return out
}

// sortedFiles flattens the union map into a stable order for reporting.
func sortedFiles(byPath map[string]File) []File {
	paths := make([]string, 0, len(byPath))
	for p := range byPath {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	out := make([]File, 0, len(paths))
	for _, p := range paths {
		out = append(out, byPath[p])
	}
	return out
}

// dumpTreeInto appends a directory's file tree to b, returning the bytes
// of file content sent (against the caller's budget). prefix is prepended
// to each path header, which is how dependency projects keep their ../
// identity. Binaries and oversized files are announced as omitted rather
// than sent.
func dumpTreeInto(b *strings.Builder, root string, budget int, prefix string) (int, error) {
	used := 0
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if skipDirs[d.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = prefix + filepath.ToSlash(rel)

		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		switch {
		case !isText(data):
			fmt.Fprintf(b, "--- %s ---\n(binary file, omitted)\n\n", rel)
		case len(data) > maxFileBytes:
			fmt.Fprintf(b, "--- %s ---\n(%d bytes, over the per-file limit, omitted)\n\n", rel, len(data))
		case used+len(data) > budget:
			fmt.Fprintf(b, "--- %s ---\n(over the context budget, omitted)\n\n", rel)
		default:
			used += len(data)
			fmt.Fprintf(b, "--- %s ---\n%s\n\n", rel, data)
		}
		return nil
	})
	if err != nil {
		return used, fmt.Errorf("read component files: %w", err)
	}
	return used, nil
}

// isText reports whether data is safe to embed in a prompt: valid UTF-8
// with no NUL bytes, the same heuristic git uses for binary detection.
func isText(data []byte) bool {
	probe := data
	if len(probe) > 8000 {
		probe = probe[:8000]
	}
	return utf8.Valid(probe) && !strings.ContainsRune(string(probe), 0)
}

// note writes a progress line when a notes writer is set.
func note(w io.Writer, msg string) {
	if w != nil {
		fmt.Fprintln(w, msg)
	}
}

