// streamProgress renders generation progress on stderr. A terminal gets
// one line updated in place; anything else (CI logs, pipes) gets a line
// every 16 KiB, because an in-place update is invisible there and total
// silence for minutes reads as a hang.
type streamProgress struct {
	w        io.Writer
	model    string
	tty      bool
	received int
	reported int
}

func newStreamProgress(w io.Writer, model string) *streamProgress {
	p := &streamProgress{w: w, model: model}
	if f, ok := w.(*os.File); ok {
		p.tty = term.IsTerminal(int(f.Fd()))
	}
	return p
}

func (p *streamProgress) delta(s string) {
	p.received += len(s)
	if p.tty {
		fmt.Fprintf(p.w, "\r\x1b[Kreceiving from %s... %s", p.model, humanBytes(p.received))
		return
	}
	if p.received-p.reported >= 16<<10 {
		fmt.Fprintf(p.w, "receiving from %s... %s\n", p.model, humanBytes(p.received))
		p.reported = p.received
