// streamProgress renders generation progress on stderr. Reasoning
// models think out loud before the reply starts, so the line has two
// phases — "thinking" while only reasoning arrives, "receiving" once
// the reply does. A terminal gets one line updated in place; anything
// else (CI logs, pipes) gets a line every 16 KiB, because an in-place
// update is invisible there and total silence for minutes reads as a
// hang.
type streamProgress struct {
	w        io.Writer
	model    string
	tty      bool
	thinking int
	received int
	reported int
}

func newStreamProgress(w io.Writer, model string) *streamProgress {
	p := &streamProgress{w: w, model: model}
	if f, ok := w.(*os.File); ok {
		p.tty = term.IsTerminal(int(f.Fd()))
	}
	return p
}

func (p *streamProgress) delta(d berget.Delta) {
	if d.Content != "" {
		p.received += len(d.Content)
	} else {
		p.thinking += len(d.Reasoning)
	}
	total := p.received + p.thinking
	if p.tty {
		fmt.Fprintf(p.w, "\r\x1b[K%s", p.line())
		return
	}
	if total-p.reported >= 16<<10 {
		fmt.Fprintf(p.w, "%s\n", p.line())
		p.reported = total
	}
}

// line renders the current phase. Once reply content arrives the
// thinking count has served its purpose and drops off the line.
func (p *streamProgress) line() string {
	if p.received > 0 {
		return fmt.Sprintf("receiving from %s... %s", p.model, humanBytes(p.received))
	}
	return fmt.Sprintf("%s thinking... %s", p.model, humanBytes(p.thinking))
}

