// resolveBergetClient builds the Berget Code client when --prompt asks
// for an implementation, and nil otherwise. The key comes from
// BERGET_API_KEY only: a flag would put a secret in shell history and
// process lists.
func resolveBergetClient(prompt, model string) (*berget.Client, error) {
	if prompt == "" {
		return nil, nil
	}
	return berget.NewClient(os.Getenv(berget.EnvAPIKey),
		berget.WithModel(model),
		berget.WithUserAgent("intropy-cli/"+version))
}

