// process lists.
func resolveBergetClient(prompt, model string) (*berget.Client, error) {
	if prompt == "" {
		return nil, nil
	}
	return berget.NewClient(os.Getenv(berget.EnvAPIKey),
		berget.WithModel(model),
		berget.WithUserAgent("intropy-cli/"+version))
}

// dotnetVerify returns the build check for the repair loop, or nil when
// there is nothing meaningful to run: the component holds no .NET
// project, or dotnet is not installed. A missing toolchain must not
// punish templates that are not .NET — verification is opportunistic,
// never a new requirement for scaffolding.
func dotnetVerify(dir string) func(ctx context.Context, dir string) error {
	if !hasDotnetProject(dir) {
		return nil
	}
	if _, err := exec.LookPath("dotnet"); err != nil {
		return nil
	}
	runner := command.ExecRunner{}
	return func(ctx context.Context, dir string) error {
		// A cold restore can take minutes; the bound keeps a wedged
		// NuGet source from holding the whole command.
		ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
		defer cancel()
		stdout, stderr, err := runner.Run(ctx, dir, "dotnet", "build", "--nologo", "--verbosity", "quiet")
		if err == nil {
			return nil
		}
		var ee *command.ExitError
		if errors.As(err, &ee) {
			return errors.New(buildErrors(string(stdout) + "\n" + string(stderr)))
		}
		return err
	}
}

// hasDotnetProject reports whether the component root holds a project or
// solution file. Root level only: a scaffold's own project lives there,
// and anything deeper is the template's business, not a build target.
func hasDotnetProject(dir string) bool {
	for _, pattern := range []string{"*.csproj", "*.sln"} {
		if matches, _ := filepath.Glob(filepath.Join(dir, pattern)); len(matches) > 0 {
			return true
		}
	}
	return false
}

// buildErrors trims a build log to the lines a repair brief needs.
// MSBuild errors match ": error "; without any, the tail of the log is
// the best available explanation. The cap keeps the next prompt small.
func buildErrors(log string) string {
	const max = 4 << 10
	var lines []string
	for _, l := range strings.Split(log, "\n") {
		if strings.Contains(l, ": error ") {
			lines = append(lines, strings.TrimSpace(l))
		}
	}
	out := strings.Join(lines, "\n")
	if out == "" {
		out = strings.TrimSpace(log)
	}
	if len(out) > max {
		out = out[:max] + "\n(truncated)"
	}
	return out
}

