	var deltas []Delta
	content, err := c.CompleteStream(context.Background(), []Message{{Role: "user", Content: "hi"}}, func(d Delta) {
		deltas = append(deltas, d)
	})
	if err != nil {
		t.Fatalf("CompleteStream: %v", err)
	}
	if content != "Hello" {
		t.Errorf("content = %q, want Hello", content)
	}
	// The role-only chunk carries no signal and is not reported; the
	// reasoning chunk is progress but never enters the reply.
	want := []Delta{{Reasoning: "hmm"}, {Content: "Hel"}, {Content: "lo"}}
	if len(deltas) != len(want) {
		t.Fatalf("deltas = %v", deltas)
	}
	for i, d := range want {
		if deltas[i] != d {
			t.Errorf("delta %d = %+v, want %+v", i, deltas[i], d)
		}
	}
}

