// repairServer answers each completion from replies in order and records
// every request's messages.
func repairServer(t *testing.T, replies ...string) (*httptest.Server, *[]chatRequest) {
	t.Helper()
	var requests []chatRequest
	call := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		decodeBody(t, r, &req)
		requests = append(requests, req)
		if call >= len(replies) {
			t.Errorf("unexpected call %d", call+1)
			return
		}
		fmt.Fprintf(w, `{"choices":[{"message":{"role":"assistant","content":%s}}]}`, quoted(replies[call]))
		call++
	}))
	t.Cleanup(srv.Close)
	return srv, &requests
}

func TestImplementRepairLoop(t *testing.T) {
	dir := writeScaffold(t, map[string]string{"Program.cs": "// TODO\n"})
	srv, requests := repairServer(t,
		`{"files":[{"path":"Program.cs","content":"broken\n"}]}`,
		`{"files":[{"path":"Program.cs","content":"fixed\n"}]}`,
	)

	builds := 0
	verify := func(_ context.Context, _ string) error {
		builds++
		if builds == 1 {
			return errors.New("Program.cs(1,1): error CS1002: ; expected")
		}
		return nil
	}

	c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
	result, err := c.Implement(context.Background(), ImplementOptions{
		Dir: dir, Prompt: "x", Template: "t", Verify: verify,
	})
	if err != nil {
		t.Fatalf("Implement: %v", err)
	}
	if !result.Verified || result.Rounds != 1 {
		t.Errorf("verified = %v, rounds = %d; want true, 1", result.Verified, result.Rounds)
	}
	if got, _ := os.ReadFile(filepath.Join(dir, "Program.cs")); string(got) != "fixed\n" {
		t.Errorf("Program.cs = %q, want the repaired contents", got)
	}
	// The repair brief carries the build errors and the bad reply.
	second := (*requests)[1].Messages
	last := second[len(second)-1].Content
	if !strings.Contains(last, "error CS1002") || !strings.Contains(last, "does not build") {
		t.Errorf("repair brief = %q", last)
	}
}

func TestImplementRepairExhausted(t *testing.T) {
	dir := writeScaffold(t, map[string]string{"Program.cs": "// TODO\n"})
	replies := make([]string, 0)
	for i := 0; i <= maxRepairRounds; i++ {
		replies = append(replies, `{"files":[{"path":"Program.cs","content":"still broken\n"}]}`)
	}
	srv, _ := repairServer(t, replies...)

	verify := func(_ context.Context, _ string) error {
		return errors.New("Program.cs(1,1): error CS1002: ; expected")
	}
	c, _ := NewClient("test-key", WithBaseURL(srv.URL+"/v1"))
	result, err := c.Implement(context.Background(), ImplementOptions{
		Dir: dir, Prompt: "x", Template: "t", Verify: verify,
	})
	if err != nil {
		t.Fatalf("Implement: %v", err)
	}
	if result.Verified || result.Rounds != maxRepairRounds {
		t.Errorf("verified = %v, rounds = %d; want false, %d", result.Verified, result.Rounds, maxRepairRounds)
	}
	if result.LastVerifyErr == nil {
		t.Error("LastVerifyErr is nil on an exhausted loop")
	}
	// The files are on disk even though they do not build: the user can
	// inspect or hand-fix what the model left behind.
	if got, _ := os.ReadFile(filepath.Join(dir, "Program.cs")); string(got) != "still broken\n" {
		t.Errorf("Program.cs = %q", got)
	}
}

