func TestBuildErrors(t *testing.T) {
	t.Run("error lines are extracted", func(t *testing.T) {
		log := "Restore complete.\nProgram.cs(3,1): error CS1002: ; expected [erp.csproj]\nProgram.cs(4,5): warning CS0219: unused\nBuild FAILED."
		got := buildErrors(log)
		if !strings.Contains(got, "error CS1002") || strings.Contains(got, "Restore complete") || strings.Contains(got, "warning") {
			t.Errorf("buildErrors = %q", got)
		}
	})

	t.Run("no error lines keeps the log tail", func(t *testing.T) {
		got := buildErrors("some weird failure\nwith details")
		if got != "some weird failure\nwith details" {
			t.Errorf("buildErrors = %q", got)
		}
	})

	t.Run("long logs are capped", func(t *testing.T) {
		long := strings.Repeat("x(1,1): error CS9999: nope\n", 500)
		if got := buildErrors(long); len(got) > 4<<10+20 {
			t.Errorf("len = %d, want capped", len(got))
		}
	})
}
EOF
